begin;
do $curate$ declare r jsonb; bid uuid; applied jsonb; begin
for r in select value from jsonb_array_elements('[{"name": "Fresh Pup Pet Grooming", "category": "Pet Services", "city": "Service area only", "address": null, "phone": "(415) 770-3935", "website": "https://freshpuppetgrooming.com/", "source_url": "https://freshpuppetgrooming.com/", "duplicate_key": "freshpuppetgrooming.com", "areas": ["Manteca"], "tags": ["mobile dog grooming", "dog grooming"], "description": "Website advertises mobile dog grooming for Manteca, including baths, haircuts and nail care. Call to confirm the mobile arrangement, your address, dog eligibility, quote and available dates. Surrounding areas are not individually established; no visitor office or holiday availability confirmed.", "note": "First-party website checked November14,2026 with fresh HTTP200. Checked identity, published4157703935 phone, mobile grooming page title, advertised dog bathing/haircut/nail services and explicit Manteca coverage. Generic surrounding-areas wording not treated as Lathrop/Tracy/Mountain House coverage. No current promotion, fixed price, medical/dental capability, credentials, insurance, quality, safety or availability adopted. No portfolio/testimonials/photos copied. Source: https://freshpuppetgrooming.com/"}, {"name": "K9 Courage Dog Training", "category": "Pet Services", "city": "Manteca", "address": null, "phone": "(209) 247-1193", "website": "https://k9couragedogtraining.com/", "source_url": "https://k9couragedogtraining.com/pages/dog-training-in-lathrop-california", "duplicate_key": "k9couragedogtraining.com", "areas": ["Lathrop", "Manteca", "Tracy"], "tags": ["dog training", "puppy training", "board and train"], "description": "Manteca-based business advertising private dog training, puppy training and board-and-train. Its official contact page names Manteca, Lathrop and Tracy. The Lathrop page says private sessions can be arranged at Lathrop parks/public spaces; board-and-train stays are in Manteca. Call/text to confirm location, suitability, program scope, quote and dates. Training stays are not listed as ordinary pet boarding.", "note": "Fresh HTTP200 official contact and Lathrop training pages checked November14,2026: identity, public call/text2092471193, Manteca base, exact training programs and named Lathrop/Manteca/Tracy coverage. No Mountain House scope inferred. Contact-page street not adopted as an unrestricted visitor office; appointment arrangements require confirmation. No training-result, behavior/safety, credential, lifetime-support, reply-time, free-evaluation availability or price guarantees adopted. No medical/behavior advice, pet-sitting/general-boarding tags, reviews or portfolio images imported. Sources: https://k9couragedogtraining.com/pages/contact-us https://k9couragedogtraining.com/pages/dog-training-in-lathrop-california"}]'::jsonb) loop
 if exists(select 1 from public.businesses where lower(name)=lower(r->>'name') or website ilike '%'||(r->>'duplicate_key')||'%' or (r->>'phone' is not null and right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),10)=right(regexp_replace(r->>'phone','[^0-9]','','g'),10))) then raise exception 'Duplicate requires individual review: %',r->>'name'; end if;
 insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values(r->>'name',r->>'category',r->>'city',r->>'address',r->>'phone',r->>'website',r->>'description','approved',true,false,null,0,'editorial_first_party',r->>'source_url','first_party_website_desk_check',now()) returning id into bid;
 insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,r->>'source_url',array['identity','public contact route','website','advertised services','explicit service cities','service limits'],array(select jsonb_array_elements_text(r->'areas')),array(select jsonb_array_elements_text(r->'tags')),r->>'note');
 select to_jsonb(b) into applied from public.businesses b where id=bid;
 insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,applied||jsonb_build_object('service_areas',r->'areas','service_tags',r->'tags','scope_note',r->>'note'),'Individually source-checked directory expansion; no seed publication',r->>'source_url');
end loop;end $curate$;
commit;
select b.id,b.name,b.city,b.verified_at,c.service_areas,c.service_tags,c.checked_at from public.businesses b join public.listing_checks c on c.business_id=b.id where b.website in ('https://freshpuppetgrooming.com/','https://k9couragedogtraining.com/');
